TriggerOraclev10g.body:
declare 
   l_table    varchar2(30) := 'MEDSUSER_MEDSLAYER';
   l_action   varchar2(1);
   l_seq      number; 
begin 
   if inserting then 
      if :new.MEDSUSER_MEDSLAYER is null then 
         :new.MEDSUSER_MEDSLAYER := to_number(sys_guid(),'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx');
      end if; 
      l_seq := :new.MEDSUSER_MEDSLAYER;
      l_action := 'I';
   elsif updating then 
      l_seq := :new.MEDSUSER_MEDSLAYER;
      l_action := 'U';
   elsif deleting then 
      l_seq := :old.MEDSUSER_MEDSLAYER;
   end if; 
   if deleting then
      cm.audit_tool.audit_delete('MEDSUSER_MEDSLAYER',l_seq);
   else
      cm.audit_tool.audit_column(l_action,'MEDSUSER_MEDSLAYER','MEDSUSER',l_seq,:old.MEDSUSER,:new.MEDSUSER);
      cm.audit_tool.audit_column(l_action,'MEDSUSER_MEDSLAYER','MEDSLAYER',l_seq,:old.MEDSLAYER,:new.MEDSLAYER);
   end if;
end b_medsuser_medslayer;
